15	 * the {@code invoices} table (Flyway V4__invoices.sql); the id is IDENTITY-generated on create. The
16	 * amount is a {@link BigDecimal} because it is money (fixed scale, no float drift).
17	 */
18	@Entity
19	@Table(name = "invoices")
20	public class Invoice {
21	
22	    @Id
23	    @GeneratedValue(strategy = GenerationType.IDENTITY)
24	    private Long id;
25	
26	    @Column(name = "project_id", nullable = false)
27	    private Long projectId;
28	
29	    @Column(nullable = false)
30	    private BigDecimal amount;
31	
32	    /**
33	     * The lifecycle status of the invoice: DRAFT when raised, SENT once the user sends it, PAID once
34	     * the user takes payment. Payment is only allowed after it has been sent.
35	     */
36	    @Column(nullable = false)
37	    private String status;
38	
39	    /** When the invoice went out. */
40	    @Column(name = "issued_date", nullable = false)
41	    private LocalDate issuedDate;
42	
43	    /** When the invoice is due to be paid. */
44	    @Column(name = "due_date", nullable = false)
45	    private LocalDate dueDate;
46	
47	    /**
48	     * The percentage taken off the invoice as a discount (0–100). The subtotal is the sum of the
49	     * invoice's line items; the discount is that percentage of the subtotal, and the final total is
50	     * the subtotal minus the discount. Defaults to zero — no discount takes nothing off
51	     * (V29__invoice_discount.sql).
52	     */
53	    @Column(name = "discount_pct", nullable = false)
54	    private BigDecimal discountPct = BigDecimal.ZERO;
55	
56	    /**
57	     * The percentage sales tax added on top of the invoice (0–100), applied AFTER the discount. The
58	     * tax is that percentage of the discounted amount (subtotal minus discount), and the final total
59	     * is the discounted amount plus that tax. Defaults to zero — no tax set adds nothing on
60	     * (V30__invoice_tax.sql).
61	     */
62	    @Column(name = "tax_pct", nullable = false)
63	    private BigDecimal taxPct = BigDecimal.ZERO;
64	
65	    protected Invoice() {
66	    }
67	
68	    public Invoice(Long projectId, BigDecimal amount, LocalDate issuedDate, LocalDate dueDate) {
69	        this.projectId = projectId;
70	        this.amount = amount;
71	        this.status = "DRAFT";
72	        this.issuedDate = issuedDate;
73	        this.dueDate = dueDate;
74	    }
75	
76	    public Long getId() {
77	        return id;
78	    }
79	
80	    public Long getProjectId() {
81	        return projectId;
82	    }
83	
84	    public BigDecimal getAmount() {
85	        return amount;
86	    }
87	
88	    /**
89	     * Set this invoice's amount to the sum of its line items. The amount is derived from the lines
90	     * (V15__invoice_line_items.sql), so it is recomputed and stored whenever a line is added.
91	     */
92	    public void setAmount(BigDecimal amount) {
93	        this.amount = amount;
94	    }
95	
96	    public String getStatus() {
97	        return status;
98	    }
99	
100	    public LocalDate getIssuedDate() {
101	        return issuedDate;
102	    }
103	
104	    public LocalDate getDueDate() {
105	        return dueDate;
106	    }
107	
108	    /** The percentage discount taken off this invoice's subtotal (0–100, zero when none is set). */
109	    public BigDecimal getDiscountPct() {
110	        return discountPct;
111	    }
112	
113	    /** The percentage sales tax added on top of this invoice (0–100, zero when none is set). */
114	    public BigDecimal getTaxPct() {
115	        return taxPct;
116	    }
117	
118	    /**
119	     * The final total owed on this invoice: the subtotal ({@link #getAmount()}) minus the percentage
120	     * discount taken off it, then the percentage sales tax added on top of what is left. This is the
121	     * figure that counts as money owed everywhere the amount due is worked out — the dashboard
122	     * outstanding total, an invoice's remaining balance and the client statement — so the discount and
123	     * tax flow through consistently. Derived in {@link BigDecimal} at money scale (no float drift), the
124	     * same derivation {@link GetInvoiceSummary} applies to the detail view.
125	     */
126	    public BigDecimal getTotal() {
127	        BigDecimal base = amount == null ? BigDecimal.ZERO : amount;
128	        BigDecimal discountPercent = discountPct == null ? BigDecimal.ZERO : discountPct;
129	        BigDecimal discount =
130	                base.multiply(discountPercent).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
131	        BigDecimal discounted = base.subtract(discount);
132	        BigDecimal taxPercent = taxPct == null ? BigDecimal.ZERO : taxPct;
133	        BigDecimal tax =
134	                discounted.multiply(taxPercent).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
135	        return discounted.add(tax);
136	    }
137	
138	    /** Send this invoice — the DRAFT -> SENT transition the send action performs. */
139	    public void markSent() {
140	        this.status = "SENT";
141	    }
142	
143	    /** Whether this invoice has been sent, and so may be paid. */
144	    public boolean isSent() {
145	        return "SENT".equals(this.status);
146	    }
